@startuml

class Organizer {
  +firstName : string
  +lastName : string
  +email : string
  +postalAddress : string
  +phoneNumber : string
  +password : string
}

class Attendee {
  +firstName : string
  +lastName : string
  +email : string
  +password : string
  +attendanceStatus : string
}

class Event {
  +kind : string
  +startDateTime : datetime
  +endDateTime : datetime
  +occasion : string
}

class Location {
  +name : string
  +address : string
}

class Task {
  +description : string
  +status : string
  +isAssignedToAttendee : boolean
}

class InvitationStatus {
  +status : string
}

Organizer "1..*" -- "0..*" Event : organizes
Organizer "0..1" -- "0..*" Event : attends
Attendee "0..*" -- "0..*" Event : attends
Attendee "0..*" -- "0..*" Event : brings

Event "1" -- "1" Location : at
Event "1" *-- "0..*" Task : has
Task "0..*" -- "0..1" Attendee : assigned to

Organizer "1" -- "0..*" Task : adds

@enduml

